//   CipherSeed interop golden vectors — the strongest tests in this repo.
//
//   Every vector below was produced by the OFFICIAL Tari wallet daemon (`tari_ootle_walletd`
//   0.39.0, esmeralda) and cross-checked in both directions:
//
//     D1  a phrase generated by tari-cipherseed, imported into a fresh daemon wallet via
//         `--seed-words`, then `create-account --key-index 0`
//     D2  a phrase generated BY the daemon (`seed-words`), imported into tari-cipherseed
//
//   Both directions produced identical keys, including `view_only_private_key` — a PRIVATE key the
//   daemon exposes directly, so these are private-key agreements, not two implementations landing
//   on the same public point by luck. Addresses were confirmed against Caravel's own shipped
//   ootle-wasm encoder, so the chain is pinned end to end: phrase -> entropy -> keys -> otl_esm_.
//
//   Upstream Tari publishes no known-answer vectors for this format (its own Rust tests are
//   self-consistent round-trips), so these fixtures ARE the external oracle. If one of them ever
//   fails, the recovery-phrase format or the derivation has changed and every wallet created under
//   the old behaviour is affected. Stop and investigate — do not update the expected values.

import { describe, expect, it } from 'vitest'
import { Network } from '@tari-project/ootle'
import { SecretKeyWallet } from '@tari-project/ootle-secret-key-wallet'
import { deriveAccountKeys, importWalletSeed } from 'tari-cipherseed'

const hex = (b: Uint8Array) => [...b].map(x => x.toString(16).padStart(2, '0')).join('')

interface Vector {
  label: string
  mnemonic: string
  ownerPublicKey: string
  viewPrivateKey: string
  viewPublicKey: string
  address: string
}

