// Rebuilds the account exactly the way the app will: phrase -> entropy -> index-0 key pair -> the
// same SecretKeyWallet the rest of Caravel already consumes.
async function deriveFromPhrase(mnemonic: string) {
  const seed = await importWalletSeed(mnemonic)
  const { ownerSecret, viewSecret } = deriveAccountKeys(seed.entropy, 0)
  const wallet = SecretKeyWallet.fromSecretKey(ownerSecret, Network.Esmeralda, viewSecret)
  return {
    ownerPublicKey: hex(await wallet.getPublicKey()),
    viewPrivateKey: hex(viewSecret),
    viewPublicKey: hex(await SecretKeyWallet.fromSecretKey(viewSecret, Network.Esmeralda).getPublicKey()),
    address: await wallet.getAddress(),
  }
}

describe.each([
  ['package -> official daemon', PACKAGE_TO_DAEMON],
  ['official daemon -> package', DAEMON_TO_PACKAGE],
] as const)('CipherSeed interop: %s', (_direction, vectors) => {
  it.each(vectors)(
    '$label reproduces the daemon-reported keys and address',
    async vector => {
      const derived = await deriveFromPhrase(vector.mnemonic)
      expect(derived.ownerPublicKey).toBe(vector.ownerPublicKey)
      // The private view key the daemon prints — a private-key match, not just a public one.
      expect(derived.viewPrivateKey).toBe(vector.viewPrivateKey)
      expect(derived.viewPublicKey).toBe(vector.viewPublicKey)
      expect(derived.address).toBe(vector.address)
    },
    30_000,
  )
})

// On first start with an imported phrase the daemon does not derive one account — it sweeps key
// indices upward, registering each, and marks the FIRST as the default. These are the ten accounts
// it recovered for the D1-0 phrase. Pinning all ten proves the index mapping is right across the
// whole recovery range rather than coincidentally right at zero, and index 0 is the one Caravel
// derives because it is the account the official wallet actually presents.
const DAEMON_RECOVERY_SWEEP = [
  'e692325a4528d687ad7b6ff9efed43c98f794be1979f56558d8f90681d6fe771', // 0 — daemon's DEFAULT
  '685dd513d785066b06c3ad41637b7766f018f95e103ddf9fe55d6c694cdf0b51',
  'c620e789f4740eb8a873e804a1848e15a8c53128e424eafc658866438422ed17',
  '1afa431b4ced6db4cce676ec8b26a9b5a3869308eaf704a35d273503e9356c48',
  'c0aac78f8661c23599bced8222e364f852157100a433718c4fbac5ace37ffb51',
  '4a678c4d94b4082af027231acf583c684068e1cfeff72c1e0105c051c1eb5452',
  'cec093fb271c545c08e5f4a3c72fdf2cffae4932dc16a5b0c22e71690c61267c',
  '6eabb115e2a0507c17449aafc7250577a0fb73c59441586382b3264d2c832460',
  '6c88bfbb63fdb301515ab19205e79014a9917ce274e441b665f351b0db64a324',
  'b4304ccc3314c46f7b6202a84395a33e4e120a2b2b321f9e58b3810453608426',
]

describe('daemon account-recovery sweep', () => {
  it('reproduces every account the daemon recovered, indices 0 through 9', async () => {
    const seed = await importWalletSeed(PACKAGE_TO_DAEMON[0].mnemonic)
    for (let index = 0; index < DAEMON_RECOVERY_SWEEP.length; index++) {
      const { ownerSecret } = deriveAccountKeys(seed.entropy, index)
      const wallet = SecretKeyWallet.fromSecretKey(ownerSecret, Network.Esmeralda)
      expect(hex(await wallet.getPublicKey()), `account index ${index}`).toBe(
        DAEMON_RECOVERY_SWEEP[index],
      )
    }
  }, 30_000)

  // Guards the one number that would strand a wallet without ever looking like an error: derive at
  // the wrong index and an imported phrase opens a real, empty, wrong account.
  it('derives index 0 — the account the official wallet presents as default', async () => {
    const seed = await importWalletSeed(PACKAGE_TO_DAEMON[0].mnemonic)
    const { ownerSecret } = deriveAccountKeys(seed.entropy, 0)
    const wallet = SecretKeyWallet.fromSecretKey(ownerSecret, Network.Esmeralda)
    expect(hex(await wallet.getPublicKey())).toBe(DAEMON_RECOVERY_SWEEP[0])
  }, 30_000)
})
